// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account, address operator, bool approved) public {
        vm.assume(account != address(0) && operator != address(0));
        vm.assume(account != operator);

        // Set approval via setApprovalForAll
        vm.prank(account);
        c.setApprovalForAll(operator, approved);

        // Now adjust admin access for the operator to ensure it's allowed
        c.adjustAdminAccess(address(this), true);

        // The rule: after setting approval, isApprovedForAll returns the same value as approved
        bool result = c.isApprovedForAll(account, operator);
        assertTrue(result == approved);
    }
}

